{"code":"import numpy as np
import json

with open("evaluations.json") as f:
    evals = json.load(f)

ings = ['jackfruit', 'textured vegetable protein', 'wheat gluten', 'coconut oil', 'tomato paste', 'soy sauce', 'apple cider vinegar', 'yeast extract', 'liquid smoke']
X = []
for e in evals:
    if e["iteration"] == 2: continue
    d = {r["ingredient"]: r["fraction"] for r in e["recipe"]}
    X.append([d[k] for k in ings])
X = np.array(X)
mean_X = np.mean(X, axis=0)
U, S, Vt = np.linalg.svd(X - mean_X, full_matrices=True)

for idx in range(4, 9):
    print(f"\nSingular value {idx} = {S[idx] if idx < len(S) else 0:.4f}:")
    for ing, v in zip(ings, Vt[idx]):
        if abs(v) > 0.1:
            print(f"  {ing:28s}: {v:+.3f}")
