{"code":"import numpy as np
import json

with open("evaluations.json") as f:
    evals = json.load(f)

for e in evals:
    if e["iteration"] == 2: continue
    d = {r["ingredient"]: r["fraction"] for r in e["recipe"]}
    sy = round(d["soy sauce"] + d["yeast extract"], 3)
    print(f"sy={sy:.3f} | Iter {e['iteration']:2d} | y={e['target_dissimilarity']:.4f}")

print("\nMean y by (soy sauce + yeast extract):")
from collections import defaultdict
groups = defaultdict(list)
for e in evals:
    if e["iteration"] == 2: continue
    d = {r["ingredient"]: r["fraction"] for r in e["recipe"]}
    sy = round(d["soy sauce"] + d["yeast extract"], 3)
    groups[sy].append(e["target_dissimilarity"])

for sy in sorted(groups):
    print(f"  soy + yeast = {sy:.3f} (n={len(groups[sy]):2d}): mean y = {np.mean(groups[sy]):.4f}, std = {np.std(groups[sy]):.4f}, values = {np.round(groups[sy], 4)}")
"}
